// prx-8mx — value props as forcing-function-backed claims (bobby's model:
// "smaller forcing functions bubble up to larger value props", and "we can look
// at the code and see how this bit of code gets us to that value prop — helpful
// for pruning and refactoring").
//
// A value prop is a falsifiable claim about what prx does. It is `backed` only
// when each of its forcing functions evaluates true RIGHT NOW (a pure `check`)
// or carries external `evidence` (a merged PR / run). A forcing function that is
// `pending` is a LEARNING GOAL, not a value prop. The doc is GENERATED by
// executing the checks, so a claim cannot overclaim — it goes green only if the
// code actually delivers it.
//
// Each backed forcing function also declares the code it `exercises`. That gives
// the reverse map (code → value props): the refactoring contract (keep the
// forcing function green and the value prop holds regardless of how the code
// changes) and the pruning lens (code that traces to no value prop is a
// candidate to delete).

import { decideAgentToolCall } from "./agents/policy_guard.ts";
import { submitRefFor } from "./submit/artifact.schema.ts";
import { verifyEffectOwnership } from "./provenance/effect-ownership.ts";

export type ForcingFunction =
  // Live + pure — green/red as of now; `exercises` is the code it traces to.
  | { readonly name: string; readonly check: () => boolean; readonly exercises: readonly string[] }
  // Backed by external proof (a merged PR, a recorded run); still traces to code.
  | { readonly name: string; readonly evidence: string; readonly exercises: readonly string[] }
  // A learning goal — not yet backed; `pending` says why. No code trace yet.
  | { readonly name: string; readonly pending: string };

export interface ValueProp {
  /** The bubbled-up claim. */
  readonly claim: string;
  /** The sharp, per-category "why not X". */
  readonly whyNot: string;
  /** The forcing functions that must hold for the claim to be backed. */
  readonly forcing: readonly ForcingFunction[];
}

