export type Backing = "backed" | "evidence" | "learning-goal";

export function backingOf(f: ForcingFunction): Backing {
  if ("check" in f) return f.check() ? "backed" : "learning-goal";
  if ("evidence" in f) return "evidence";
  return "learning-goal";
}

/** A value prop is backed iff none of its forcing functions are learning goals. */
export function isValuePropBacked(vp: ValueProp): boolean {
  return vp.forcing.every((f) => backingOf(f) !== "learning-goal");
}

/** The code each forcing function exercises (empty for learning goals). */
export function exercisedBy(f: ForcingFunction): readonly string[] {
  return "exercises" in f ? f.exercises : [];
}

/**
 * The reverse map: code symbol → the value-prop claims it helps deliver. The
 * pruning/refactoring lens — a symbol absent here is unattributed; a green
 * forcing function is the contract a refactor must keep holding.
 */
export function codeToValueProps(): Map<string, string[]> {
  const map = new Map<string, string[]>();
  for (const vp of VALUE_PROPS) {
    for (const f of vp.forcing) {
      for (const sym of exercisedBy(f)) {
        const arr = map.get(sym) ?? [];
        if (!arr.includes(vp.claim)) arr.push(vp.claim);
        map.set(sym, arr);
      }
    }
  }
  return map;
}

const BANNER =
  "<!-- GENERATED by `bun packages/prx/scripts/gen-value-props.ts` by EXECUTING the " +
  "forcing-function checks in packages/prx/src/value_props.ts. A claim is BACKED only if its " +
  "checks pass right now — it cannot overclaim. Drift-checked by packages/prx/test/value_props.test.ts. " +
  "Do not edit by hand. -->";

function forcingLine(f: ForcingFunction): string {
  const backing = backingOf(f);
  const mark = backing === "backed" ? "✅" : backing === "evidence" ? "📎" : "⚠️";
  const tail =
    "evidence" in f ? ` — ${f.evidence}` : "pending" in f ? ` — learning goal: ${f.pending}` : "";
  const exercises =
    "exercises" in f && f.exercises.length > 0
      ? `\n  - exercises: ${f.exercises.join(", ")}`
      : "";
  return `- ${mark} ${f.name}${tail}${exercises}`;
}

/**
 * Render the value-props doc by EXECUTING every forcing function. The committed
 * doc therefore reflects what the code actually delivers at generation time; the
 * drift test fails if a claim's backing changes without regenerating.
 */
export function generateValuePropsDoc(): string {
  const lines: string[] = [
    "# prx — value props (forcing-function-backed)",
    "",
    BANNER,
    "",
    "Each claim is **backed** only when its forcing functions hold now (a passing pure",
    "check ✅, or external evidence 📎). A ⚠️ forcing function is a **learning goal**, not a",
    "value prop. `exercises` is the code that delivers the claim — the refactoring contract",
    "(keep it green) and the pruning lens (code that traces to nothing is a prune candidate).",
    "",
  ];

  for (const vp of VALUE_PROPS) {
    const status = isValuePropBacked(vp) ? "BACKED" : "LEARNING GOAL";
    lines.push(`## ${vp.claim}  — ${status}`, "");
    lines.push(`**Why not X:** ${vp.whyNot}`, "");
    for (const f of vp.forcing) lines.push(forcingLine(f));
    lines.push("");
  }

  lines.push("## Code → value props (pruning / refactoring lens)", "");
  const reverse = [...codeToValueProps().entries()].sort(([a], [b]) => a.localeCompare(b));
  for (const [sym, claims] of reverse) {
    lines.push(`- \`${sym}\` → ${claims.map((c) => `"${c}"`).join("; ")}`);
  }
  lines.push("");

  return lines.join("\n");
}
